#!/usr/bin/env bash
set -e

echo "=================================================="
echo "  DocuShift - پچ قطعی و نهایی راه‌اندازی سرور"
echo "=================================================="

# ۱. رفتن به مسیر اصلی پروژه
if [ -d "/root/docushift" ]; then
  cd "/root/docushift"
elif [ -d "/root/Docpersian" ]; then
  cd "/root/Docpersian"
elif [ -f "server.ts" ]; then
  echo "در پوشه فعلی پروژه هستیم."
else
  echo "پوشه docushift یافت نشد! لطفاً دستور cd /root/docushift را اجرا کنید."
  exit 1
fi

echo "--> مسیر جاری: $(pwd)"

# ۲. پاکسازی کش‌های قدیمی و جلسات ناقص
echo "--> ۱. پاکسازی کش‌های موقت و فایل‌های قدیمی..."
rm -rf jobs_storage/cache/* jobs_storage/uploads_temp/*

# ۳. توقف کامل پروسه‌های معلق قبلی و آزادسازی پورت ۳۰۰۰
echo "--> ۲. آزادسازی کامل پورت ۳۰۰۰..."
pm2 delete all 2>/dev/null || true
pkill -9 -f "server.js" 2>/dev/null || true
pkill -9 -f "tsx" 2>/dev/null || true
if command -v fuser >/dev/null 2>&1; then
  fuser -k -9 3000/tcp 2>/dev/null || true
fi
sleep 1

# ۴. استخراج کدهای اصلاح‌شده و فایل اکوسیستم PM2
echo "--> ۳. استخراج فایل‌های اصلاح‌شده و ecosystem.config.cjs..."
cat << 'EOF_PATCH' | base64 -d | tar -xz --overwrite

EOF_PATCH

# ۵. اطمینان از نصب بودن وابستگی undici و کامپایل
echo "--> ۴. بررسی پکیج‌ها و کامپایل نهایی (npm run build)..."
npm install --no-audit --no-fund undici 2>/dev/null || true
npm run build

# ۶. تنظیم و بازگشایی پورت‌های فایروال (80 و 3000)
echo "--> ۵. بررسی فایروال سرور..."
if command -v ufw >/dev/null 2>&1; then
  ufw allow 80/tcp 2>/dev/null || true
  ufw allow 3000/tcp 2>/dev/null || true
fi
if command -v iptables >/dev/null 2>&1; then
  iptables -I INPUT -p tcp --dport 80 -j ACCEPT 2>/dev/null || true
  iptables -I INPUT -p tcp --dport 3000 -j ACCEPT 2>/dev/null || true
fi

# ۷. پیکربندی قطعی Nginx برای پورت ۸۰
if command -v nginx >/dev/null 2>&1; then
  echo "--> ۶. پیکربندی خودکار Nginx برای پروکسی پورت ۸۰ به ۳۰۰۰..."
  mkdir -p /var/lib/nginx/body /var/cache/nginx/client_temp /tmp/nginx_upload 2>/dev/null || true
  chmod -R 777 /var/lib/nginx /tmp/nginx_upload 2>/dev/null || true
  tee /etc/nginx/sites-available/docushift >/dev/null << 'EOF_NGINX'
server {
    listen 80 default_server;
    listen [::]:80 default_server;
    server_name _;
    client_max_body_size 0;

    location / {
        proxy_pass http://127.0.0.1:3000;
        proxy_http_version 1.1;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "upgrade";
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_read_timeout 3600s;
        proxy_send_timeout 3600s;
        proxy_request_buffering off;
        proxy_buffering off;
    }
}
EOF_NGINX
  rm -f /etc/nginx/sites-enabled/default 2>/dev/null || true
  ln -sf /etc/nginx/sites-available/docushift /etc/nginx/sites-enabled/ 2>/dev/null || true
  nginx -t 2>/dev/null && systemctl restart nginx 2>/dev/null || true
fi

# ۸. استارت سرویس با ecosystem.config.cjs در PM2
echo "--> ۷. راه‌اندازی مطمئن DocuShift از طریق ecosystem.config.cjs..."
pm2 start ecosystem.config.cjs
pm2 save 2>/dev/null || true

# ۹. تست سلامت سرویس
echo "--> ۸. تست عملکرد و تست پاسخگویی سرور..."
HEALTH_OK=0
for attempt in 1 2 3 4 5; do
  RESP=$(curl -s http://127.0.0.1:3000/api/health 2>/dev/null || echo "")
  if echo "$RESP" | grep -q '"status":"ok"'; then
    HEALTH_OK=1
    echo "✅ پورت ۳۰۰۰ با موفقیت پاسخ داد: $RESP"
    break
  fi
  sleep 1
done

if [ "$HEALTH_OK" -eq 0 ]; then
  echo "⚠️ لاگ‌های خطایابی پروسه:"
  pm2 logs docushift --lines 15 --nostream 2>/dev/null || true
fi

SERVER_IP=$(hostname -I 2>/dev/null | awk '{print $1}')
if [ -z "$SERVER_IP" ] || [ "$SERVER_IP" = "127.0.0.1" ]; then
  SERVER_IP="141.98.210.131"
fi

# ۱۰. ایجاد دستور سراسری docushift-update برای به‌روزرسانی آسان در دفعات بعد
tee /usr/local/bin/docushift-update >/dev/null << 'EOF_UPDATER'
#!/usr/bin/env bash
cd /root/docushift 2>/dev/null || cd /root/Docpersian 2>/dev/null
curl -sL "https://dpaste.org/sKKy2/raw" | bash
EOF_UPDATER
chmod +x /usr/local/bin/docushift-update 2>/dev/null || true

echo "=================================================="
echo "  🎉 سامانه با حداکثر سرعت، بدون گیر کردن صفحه و مصرف بهینه توکن آماده است!"
echo ""
echo "  🌐 آدرس‌های ورود در مرورگر:"
echo "  ۱. روش اصلی و توصیه‌شده (بدون نیاز به نوشتن پورت):"
echo "     http://${SERVER_IP}"
echo ""
echo "  ۲. با پورت ۳۰۰۰ (حتماً با http وارد شوید):"
echo "     http://${SERVER_IP}:3000"
echo ""
echo "  💡 از این به بعد از هر جای سرور می‌توانید با دستور زیر پروژه را به‌روزرسانی کنید:"
echo "     docushift-update"
echo "=================================================="
